// ---- lazy poly_mix accumulator (RK_LAZYCHAIN) ----
struct RkAcc { uint32_t lo[4]; uint32_t hi[4]; };   // S_j = hi*2^32+lo, invariant hi < P
__device__ __forceinline__ static uint32_t rk_mulhi(uint32_t a, uint32_t b) { return uint32_t((uint64_t(a) * uint64_t(b)) >> 32); }
__device__ __forceinline__ static uint32_t rk_umin(uint32_t a, uint32_t b) { return a < b ? a : b; }
__device__ __forceinline__ static RkAcc rk_acc(FpExt b) { RkAcc s; for (int j = 0; j < 4; j++) { s.lo[j] = 0; s.hi[j] = b.elems[j].asRaw(); } return s; }
__device__ __forceinline__ static RkAcc rk_acc(const RkAcc& s) { return s; }
template <typename A> __device__ __forceinline__ static RkAcc rk_link(const A& base, Fp c, const FpExt& pm) {
#ifdef EF_WIDE
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint64_t t = ((uint64_t(s.hi[j]) << 32) | s.lo[j]) + uint64_t(cr) * uint64_t(pm.elems[j].asRaw());
    uint32_t h = uint32_t(t >> 32);
    s.lo[j] = uint32_t(t); s.hi[j] = rk_umin(h, h - Fp::P);
  }
  return s;
#else
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint32_t p = pm.elems[j].asRaw();
    uint32_t pl = cr * p, ph = rk_mulhi(cr, p);
    uint32_t n = s.lo[j] + pl;
    uint32_t h = s.hi[j] + ph + (n < pl ? 1u : 0u);   // < P + 0.47P + 1 < 2P
    s.lo[j] = n; s.hi[j] = rk_umin(h, h - Fp::P);
  }
  return s;
#endif
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link(const A& base, FpExt c, const FpExt& pm) {
  RkAcc s = rk_acc(base); FpExt p = c * pm;
  for (int j = 0; j < 4; j++) { uint32_t h0 = rk_umin(s.hi[j], s.hi[j] - Fp::P); uint32_t h = h0 + p.elems[j].asRaw(); s.hi[j] = rk_umin(h, h - Fp::P); }
  return s;
}
// no-fold variant: input hi < P, output hi < P + 0.47P + 1 < 2P (fits u32); the next link must fold.
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf(const A& base, Fp c, const FpExt& pm) {
#ifdef EF_WIDE
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint64_t t = ((uint64_t(s.hi[j]) << 32) | s.lo[j]) + uint64_t(cr) * uint64_t(pm.elems[j].asRaw());
    s.lo[j] = uint32_t(t); s.hi[j] = uint32_t(t >> 32);
  }
  return s;
#else
  RkAcc s = rk_acc(base); uint32_t cr = c.asRaw();
  for (int j = 0; j < 4; j++) {
    uint32_t p = pm.elems[j].asRaw();
    uint32_t pl = cr * p, ph = rk_mulhi(cr, p);
    uint32_t n = s.lo[j] + pl;
    s.hi[j] = s.hi[j] + ph + (n < pl ? 1u : 0u);
    s.lo[j] = n;
  }
  return s;
#endif
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf(const A& base, FpExt c, const FpExt& pm) {
  return rk_link(base, c, pm);
}
__device__ __forceinline__ static FpExt rk_fin(const RkAcc& s) {
  uint32_t r[4];
  for (int j = 0; j < 4; j++) {
    uint32_t m = s.lo[j] * Fp::M;
    uint32_t t = s.hi[j] - rk_mulhi(m, Fp::P);
    r[j] = rk_umin(t, t + Fp::P);
  }
  return FpExt(Fp::fromRaw(r[0]), Fp::fromRaw(r[1]), Fp::fromRaw(r[2]), Fp::fromRaw(r[3]));
}


// ---- lazyfp.py: lazy [0, 2P) Fp results (see evalfast/lazyfp.py for the bounds) ----
__device__ __forceinline__ static ::risc0::Fp ef_ladd(::risc0::Fp a, ::risc0::Fp b) { return ::risc0::Fp::fromRaw(a.asRaw() + b.asRaw()); }
__device__ __forceinline__ static ::risc0::Fp ef_lsub(::risc0::Fp a, ::risc0::Fp b) { return ::risc0::Fp::fromRaw(a.asRaw() + (::risc0::Fp::P - b.asRaw())); }
__device__ __forceinline__ static ::risc0::Fp ef_lmul(::risc0::Fp a, ::risc0::Fp b) {
  const uint32_t x = a.asRaw(), y = b.asRaw(); const uint32_t lo = x * y; const uint32_t hi = uint32_t((uint64_t(x) * uint64_t(y)) >> 32);
  const uint32_t m = lo * ::risc0::Fp::M; return ::risc0::Fp::fromRaw(hi - uint32_t((uint64_t(m) * uint64_t(::risc0::Fp::P)) >> 32) + ::risc0::Fp::P);
}

// ---- close.py: lazy closures B + u * PM_k with a precomputed NBETA-folded constant table ----
__device__ __forceinline__ static uint64_t ef_madw(uint32_t a, uint32_t b, uint64_t c) {
#ifdef EF_MADW_ASM
  uint64_t d; asm("mad.wide.u32 %0, %1, %2, %3;" : "=l"(d) : "r"(a), "r"(b), "l"(c)); return d;
#else
  return c + uint64_t(a) * uint64_t(b);
#endif
}
__device__ __forceinline__ static uint64_t ef_fold64(uint64_t t) {
  uint32_t h = uint32_t(t >> 32), f = h - Fp::P; h = h < f ? h : f;
  return (uint64_t(h) << 32) | uint32_t(t);
}
// pm row j of the NBETA-folded 4x4 matrix of constant k
#define EF_PMROW(b, n) const uint32_t X[4][4] = {{b.x, n.z, n.y, n.x}, {b.y, b.x, n.z, n.y}, {b.z, b.y, b.x, n.z}, {b.w, b.z, b.y, b.x}}
__device__ __forceinline__ static void rk_cl_acc(RkW& w, const FpExt& u, uint32_t k) {
  const uint32_t a0 = u.elems[0].asRaw(), a1 = u.elems[1].asRaw(), a2 = u.elems[2].asRaw(), a3 = u.elems[3].asRaw();
  const uint4 b = reinterpret_cast<const uint4*>(ef_pm_raw)[k], n = reinterpret_cast<const uint4*>(ef_pmn_raw)[k];
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = (uint64_t(w.hi[j]) << 32) | w.lo[j];
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    w.lo[j] = uint32_t(t); w.hi[j] = uint32_t(t >> 32);
  }
}
__device__ __forceinline__ static RkW rk_cl0(const FpExt& b, const FpExt& u, uint32_t k) {
  RkW w; for (int j = 0; j < 4; j++) { w.lo[j] = 0; w.hi[j] = b.elems[j].asRaw(); }
  rk_cl_acc(w, u, k); return w;
}

// ---- linkext.py: rk_link with an FpExt term, products accumulated lazily ----
template <typename A> __device__ __forceinline__ static RkAcc rk_link_k(const A& base, Fp c, uint32_t k) { return rk_link(base, c, EF_PM(k)); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_k(const A& base, Fp c, uint32_t k) { return rk_link_nf(base, c, EF_PM(k)); }
template <typename A> __device__ __forceinline__ static RkAcc rk_link_k(const A& base, FpExt c, uint32_t k) {
  RkAcc s = rk_acc(base);
  const uint32_t a0 = c.elems[0].asRaw(), a1 = c.elems[1].asRaw(), a2 = c.elems[2].asRaw(), a3 = c.elems[3].asRaw();
  const uint4 b = reinterpret_cast<const uint4*>(ef_pm_raw)[k], n = reinterpret_cast<const uint4*>(ef_pmn_raw)[k];
  EF_PMROW(b, n);
  for (int j = 0; j < 4; j++) {
    uint64_t t = ef_fold64((uint64_t(s.hi[j]) << 32) | s.lo[j]);
    t = ef_fold64(ef_madw(a1, X[j][1], ef_madw(a0, X[j][0], t)));
    t = ef_fold64(ef_madw(a3, X[j][3], ef_madw(a2, X[j][2], t)));
    s.lo[j] = uint32_t(t); s.hi[j] = uint32_t(t >> 32);
  }
  return s;
}
template <typename A> __device__ __forceinline__ static RkAcc rk_link_nf_k(const A& base, FpExt c, uint32_t k) { return rk_link_k(base, c, k); }
